'use strict';
const ITEMS = [
 {id:'cn-marketing',pillar:'changes',category:'regulation',region:'中国',source:'中国网信网',date:'2026-04-24',dateLabel:'原文发布',title:'金融产品网络营销：从规则文本看业务边界',original:'金融产品网络营销管理办法',url:'https://www.cac.gov.cn/2026-04/24/c_1778769008779432.htm',question:'内容审核、平台委托与营销人员责任，应该如何转化为可执行的管理动作？',checks:['对照第二条与定义条款，确认具体活动是否属于商业性宣传推介。','对照第七条、第十六条，梳理审核、授权与回溯责任。','区分公布时间、施行时间与具体适用，不用标题代替条文判断。'],counter:'研究活动与商业性营销的具体边界需要结合实际行为判断；不能只因涉及保险就一概下结论。',locator:'页面公告；第二条、第七条、第十六条、第三十九条',ai:false},
 {id:'coalition',pillar:'emerges',category:'model',region:'全球',source:'Coalition',date:'2026-03-05',dateLabel:'原文发布',title:'主动保险：风险预防能否成为商业模式的一部分？',original:'2026 Cyber Claims Report · 发布公告',url:'https://www.coalitioninc.com/announcements/2026-cyber-claims-report',question:'把安全服务嵌入保障关系，究竟改变了风险承担、客户价值，还是只增加了服务成本？',checks:['识别保险保障、安全工具与事件响应分别由谁提供、谁付费。','检查损失改善是否控制了承保筛选、客户规模与风险暴露差异。','核验持续服务收入与保险收益的关系，区分业务结构与营销名称。'],counter:'更好的赔付表现可能来自客户筛选、业务组合或承保条件；公司自述不能独立证明服务的因果效果。',locator:'公告的报告说明与 About Coalition 段落',ai:true},
 {id:'eiopa-opinion',pillar:'matters',category:'regulation',region:'欧洲',source:'EIOPA',date:'2025-08-06',dateLabel:'原文发布',title:'保险 AI 治理：从模型能力转向责任与风险管理',original:'Opinion on Artificial Intelligence governance and risk management',url:'https://www.eiopa.europa.eu/publications/opinion-artificial-intelligence-governance-and-risk-management_en',question:'同一个 AI 系统用于核保、理赔和客服时，治理要求应如何随风险变化？',checks:['对照正式意见，识别适用对象与业务场景。','追踪数据治理、解释、人工监督与记录要求。','区分监管意见、法律义务与项目自行选择的控制标准。'],counter:'统一加码控制可能增加低风险场景的成本；风险与措施的比例关系同样需要证据。',locator:'发布页 Description 与正式 Opinion PDF',ai:true},
 {id:'coalition-risk',pillar:'changes',category:'risk',region:'全球',source:'Coalition',date:'2026-03-05',dateLabel:'原文发布',title:'网络风险研究：先看统计口径，再看赔案趋势',original:'2026 Cyber Claims Report · 风险线索',url:'https://www.coalitioninc.com/announcements/2026-cyber-claims-report',question:'赔案频率、损失程度与勒索要价的变化，是否指向同一种风险机制？',checks:['分开记录报告年份与实际数据覆盖期间。','检查样本区域、保单数量、结案口径和事件分类。','区分勒索要价、实付金额、总损失与保险赔付。'],counter:'单家公司样本不能直接外推整个市场；组合变化与事件分类也可能影响同比结果。',locator:'公告 Additional key takeaways 与样本说明',ai:false},
 {id:'naic-ai',pillar:'matters',category:'regulation',region:'美国',source:'NAIC',date:'2023-12-04',dateLabel:'历史资料',title:'AI 治理的责任链：第三方模型如何纳入管理？',original:'NAIC Members Approve Model Bulletin on Use of AI by Insurers',url:'https://content.naic.org/article/naic-members-approve-model-bulletin-use-ai-insurers',question:'模型由供应商提供时，哪些决策责任、验证记录与消费者保护要求仍由保险机构承担？',checks:['把模型公告与各州实际采纳、实施文件分开核验。','对照书面 AI 治理计划、第三方合同与验证要求。','检查“使用模型”和“支持决策”是否都被纳入控制范围。'],counter:'模型公告本身不等于各州统一生效的法律；当前适用状态必须进一步查证。',locator:'发布公告的治理计划、第三方合同与验证段落',ai:true},
 {id:'lemonade',pillar:'emerges',category:'model',region:'美国',source:'Lemonade · SEC 文件',date:'2023-Q2',dateLabel:'报告期间',title:'Synthetic Agents：一个名字，还是一种新机制？',original:'Lemonade Q2 2023 Shareholder Letter',url:'https://www.sec.gov/Archives/edgar/data/1691421/000169142123000092/lmndshareholderletterq22.htm',question:'判断“Agent”前，先核验资本从哪里来、回款如何分配、损失由谁承担。',checks:['读取 Synthetic Agents Detail，核对现金流与资本结构。','区分融资安排、软件自动化和 AI 自主决策。','以历史文件解释机制，不据此认定当前安排仍相同。'],counter:'名称包含 Agents 并不能证明 AI 商业模式创新；经济结构与技术自主程度应分别判断。',locator:'股东信第15页 Synthetic Agents Detail',ai:true}
];
const VIEW = {all:['发现保险的下一步。','什么重要，什么在变，什么正在诞生。','总览','精选研究线索'],matters:['什么值得认真研究？','从监管与一手文件中，寻找重要问题。','什么重要','重要议题'],changes:['变化，发生在哪里？','分清规则变化、风险变化与统计口径变化。','什么在变','变化研究线索'],emerges:['什么正在诞生？','用经济结构与证据，审视保险新商业模式。','什么在诞生','新商业模式线索'],ai:['AI 如何改变保险？','从风险、价值与收入三个维度验证变化。','AI 商业模式','AI 研究线索']};
const PILLAR_NAMES={matters:'重要',changes:'变化',emerges:'新生'};
const state={view:'all',category:'all',query:''};
const $=s=>document.querySelector(s);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function selectItems(){return ITEMS.filter(item=>(state.view==='all'||(state.view==='ai'?item.ai:item.pillar===state.view))&&(state.category==='all'||item.category===state.category)&&(!state.query||[item.title,item.source,item.original,item.region,item.question].join(' ').toLowerCase().includes(state.query.toLowerCase())));}
function render(){const list=selectItems();$('#cards').innerHTML=list.map((item,i)=>`<article class="card ${i===0&&state.view==='all'&&state.category==='all'&&!state.query?'featured':''}"><div class="card-meta"><span class="tag ${item.pillar}">${PILLAR_NAMES[item.pillar]}</span><span>${escape(item.region)} · ${item.dateLabel}</span><time ${item.date.includes('Q')?'':`datetime="${item.date}"`}>${escape(item.date)}</time></div><h3 class="card-title"><button class="title-button" data-detail="${item.id}">${escape(item.title)}</button></h3><p class="question"><strong>研究问题</strong> · ${escape(item.question)}</p><div class="card-footer"><span class="source">${escape(item.source)}</span><div class="card-links"><button data-detail="${item.id}">展开线索</button><a href="${item.url}" target="_blank" rel="noopener noreferrer" aria-label="阅读 ${escape(item.source)} 原文（新窗口）">阅读原文</a></div></div></article>`).join('');$('#result-count').textContent=list.length+' 条';$('#empty').hidden=list.length>0;document.querySelectorAll('[data-detail]').forEach(b=>b.addEventListener('click',()=>showItem(b.dataset.detail)));}
function changeView(view){state.view=view;state.category='all';state.query='';$('#search').value='';const v=VIEW[view];$('#view-title').textContent=v[0];$('#view-subtitle').textContent=v[1];$('#crumb').textContent=v[2];$('#feed-title').textContent=v[3];document.querySelectorAll('.nav-item[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});document.querySelectorAll('.pillar').forEach(b=>b.classList.toggle('selected',b.dataset.view===view));updateFilters();render();}
function updateFilters(){document.querySelectorAll('.filter').forEach(b=>{const yes=b.dataset.category===state.category;b.classList.toggle('active',yes);b.setAttribute('aria-pressed',String(yes));});}
function openDetail(kicker,html){$('#detail-kicker').textContent=kicker;$('#detail-content').innerHTML=html;$('#detail').showModal();$('#detail').scrollTop=0;}
function showItem(id){const item=ITEMS.find(x=>x.id===id);if(!item)return;openDetail('RESEARCH NOTE · '+PILLAR_NAMES[item.pillar],`<h2 id="detail-title">${escape(item.title)}</h2><div class="detail-meta"><span>${escape(item.source)}</span><span>${item.dateLabel}：${escape(item.date)}</span><span>线索整理：2026-09-30</span></div><h3>一手资料线索</h3><p>${escape(item.original)}</p><p>原文定位：${escape(item.locator)}。本页保留最小线索元数据与链接；具体事实请回查原始文件。</p><h3>编辑研究问题</h3><p class="detail-question">${escape(item.question)}</p><h3>下一步核验</h3><ul>${item.checks.map(x=>'<li>'+escape(x)+'</li>').join('')}</ul><h3>最强反方解释</h3><p>${escape(item.counter)}</p><a class="original-link" href="${item.url}" target="_blank" rel="noopener noreferrer">阅读一手原文</a><div class="details-footer"><p>状态：人工研究线索。尚未形成断言级证据链，也未判定为已证实趋势或正式“新物种”。</p><a href="https://github.com/alongor666/InsurHOT/issues/new" target="_blank" rel="noopener noreferrer">提交附证据的更正</a></div>`);}
function showMethod(){openDetail('EVIDENCE & METHOD',`<h2 id="detail-title">先看证据，再形成判断。</h2><p>InsurHOT 关注保险行业什么重要、什么正在变化、什么正在诞生。热度只是辅助信号。</p><h3>本期如何阅读</h3><ul><li>一手资料线索：只登记原始资料的名称、日期、定位与链接。</li><li>编辑研究问题：是待验证的问题，不是事实结论。</li><li>公司文件：能证明公司曾披露某项信息，不能独立证明其效果。</li><li>历史资料：用于研究机制，不直接代表当下状态。</li></ul><h3>时间与来源口径</h3><p>原文日期来自资料页面或报告期间；线索整理日期是本期整理时间。两者都不用于宣称全球首次出现。两张 Coalition 卡片引用同一原文，不计作两份独立证据。</p><h3>评价方法</h3><p>商业模式研究先核验风险承担、价值创造与收入结构。产品研究先确认保障、除外、触发条件与可比集合。本版没有评分、产品榜单或已证实趋势标签。</p><h3>本期状态</h3><p>六条人工整理线索，支持浏览、筛选与回查原文。自动采集、付费模型、实时更新和结构化证据接口尚未接入。</p><a class="original-link" href="https://github.com/alongor666/InsurHOT/blob/main/docs/phase0/InsurHOT-Phase0-Spec.md" target="_blank" rel="noopener noreferrer">查看项目方法规格</a><div class="details-footer"><a href="https://github.com/alongor666/InsurHOT/issues/new" target="_blank" rel="noopener noreferrer">提交附证据的更正</a></div>`);}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>changeView(b.dataset.view)));
document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>{state.category=b.dataset.category;updateFilters();render();}));
$('#search').addEventListener('input',e=>{state.query=e.target.value.trim();render();});
$('#reset').addEventListener('click',()=>changeView('all'));
['#method-button','#method-rail','#about-button'].forEach(id=>$(id).addEventListener('click',showMethod));
$('#close-detail').addEventListener('click',()=>$('#detail').close());
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
changeView('all');
